from datetime import datetime, timedelta

def parse_date(date_str):
    if not date_str or "left blank" in date_str:
        return None
    # Remove day of week (e.g., "Mon., ")
    clean_str = re.sub(r'^[A-Za-z]+,\s+', '', date_str)
    # Handle abbreviated months
    months = {
        'Jan': 'January', 'Feb': 'February', 'Mar': 'March', 'Apr': 'April',
        'May': 'May', 'Jun': 'June', 'Jul': 'July', 'Aug': 'August',
        'Sep': 'September', 'Oct': 'October', 'Nov': 'November', 'Dec': 'December'
    }
    for abbr, full in months.items():
        clean_str = re.sub(rf'\b{abbr}\.', full, clean_str)

    try:
        return datetime.strptime(clean_str, '%B %d, %Y')
    except ValueError:
        return None

def extract_data(directory):
