            sheet_data = {}
            # Extract Staff Badge
            badge_match = re.search(r'Staff badge</th><td[^>]*>(?:<strong[^>]*>)?([^<]+)', part)
            if badge_match:
                badge = badge_match.group(1).strip()
                sheet_data['badge'] = badge

                # Extract all table rows
                rows = re.findall(r'<tr.*?>(.*?)</tr>', part, re.DOTALL)
                for row in rows:
                    th_match = re.search(r'<th.*?>(.*?)</th>', row)
                    td_match = re.search(r'<td.*?>(.*?)</td>', row, re.DOTALL)
                    if th_match and td_match:
                        key = re.sub('<[^<]+?>', '', th_match.group(1)).strip()
                        val = re.sub('<[^<]+?>', '', td_match.group(1)).strip()
                        if val != "— left blank on form —":
                            sheet_data[key] = val
                sheets.append(sheet_data)
        return sheets

    # Parse all files
