from datetime import datetime, timedelta

def parse_date(date_str):
    if not date_str or "left blank" in date_str:
        return None
    # Remove day of week (e.g., "Fri., ")
    clean_str = re.sub(r'^[A-Za-z]+,\s+', '', date_str)
    # Handle abbreviations like "Feb." or "Jan."
    clean_str = clean_str.replace('Jan.', 'Jan').replace('Feb.', 'Feb').replace('Mar.', 'Mar')
    clean_str = clean_str.replace('Apr.', 'Apr').replace('May', 'May').replace('Jun.', 'Jun')
    clean_str = clean_str.replace('Jul.', 'Jul').replace('Aug.', 'Aug').replace('Sep.', 'Sep')
    clean_str = clean_str.replace('Oct.', 'Oct').replace('Nov.', 'Nov').replace('Dec.', 'Dec')

    formats = ['%B %d, %Y', '%b %d, %Y']
    for fmt in formats:
        try:
            return datetime.strptime(clean_str, fmt)
        except ValueError:
            continue
    return None

def is_business_day(date, holidays):
    if date.weekday() >= 5:
        return False
    if date in holidays:
        return False
    return True

def get_business_days_diff(start, end, holidays):
    # This is used to check if removed no earlier than 10 business days after posted
    # We count business days between (start, end]
    count = 0
    curr = start + timedelta(days=1)
    while curr <= end:
        if is_business_day(curr, holidays):
            count += 1
        curr += timedelta(days=1)
    return count

