    with open(path, 'r', encoding='utf-8') as f:
        reader = csv.reader(f, delimiter='\t')
        rows = list(reader)

    if not rows:
        return {}

    # Find header row (the one starting with 'attribute')
    header_idx = -1
    for i, row in enumerate(rows):
        if row and row[0] == 'attribute':
            header_idx = i
            break

    if header_idx == -1:
        return {}

    header = rows[header_idx]
    # Columns are rec.01, rec.02...
    # We map attribute name -> { rec_id: value }
    for i in range(1, len(header)):
        rec_id = header[i]
        for r_idx in range(header_idx + 1, len(rows)):
            row = rows[r_idx]
            if r_idx < len(row):
                attr = row[0]
                val = row[i]
                if attr not in data:
                    data[attr] = {}
                data[attr][rec_id] = val
