                val = data[attr].get(rec_id)
                if val and val != '~':
                    return val, f"{attr.split('.')[0]}_file_placeholder_logic" # Logic handled by caller

    # Fallback search
    if fallback_data is not None and fallback_attr in fallback_data:
        worker_map = fallback_data.get('worker.key', {})
        for rec_id, w_key in worker_map.items():
            if w_key == worker_key:
                val = fallback_data[fallback_attr].get(rec_id)
                if val and val != '~':
                    return val, "fallback"

    return None, None

