import json
import datetime

def parse_iso_week(week_str):
    """Parses YYYY-Www-D into a datetime object."""
    if not week_str or week_str == '~':
        return None
    try:
        parts = week_str.split('-')
        year = int(parts[0])
        week = int(parts[2].split('-')[0] if len(parts) > 2 else parts[1].split('W')[1]) # Handle W format
        # The format is YYYY-Www-D
        # Example: 2026-W11-1
        year = int(parts[0])
        week = int(parts[1][1:])
        day = int(parts[2])
        return datetime.datetime.strptime(f'{year}-W{week:02d}-{day}', '%G-W%V-%u')
    except (ValueError, IndexError):
        return None

def load_tsv(filepath):
    data = {}
    try:
        with open(filepath, 'r') as f:
            lines = f.readlines()
            if not lines:
                return data

            # Find header and data rows
            rows = []
            for line in lines:
                if line.startswith('#'):
                    continue
                parts = line.strip().split('\t')
                if parts:
                    rows.append(parts)

            if not rows:
                return data

            header = rows[0]
            for row in rows[1:]:
                if len(row) == len(header):
                    for i, val in enumerate(row):
                        data[header[i]] = val

            # The TSV is cross-tab: rows are attributes, columns are records
            # We need to transform it so we can access by attribute and record ID
            # But the instructions say "each COLUMN after the first is one record"
            # and "each ROW is one attribute".

            # Let's rebuild: records[rec_id][attribute] = value
            records = {}
            for col_idx in range(1, len(header)):
                rec_id = header[col_idx]
                records[rec_id] = {}
                for row_idx in range(1, len(rows)):
                    attr = rows[row_idx][0]
                    val = rows[row_idx][col_idx]
                    records[rec_id][attr] = val
            return records
    except Exception:
        return {}

def main(directory):
