from datetime import datetime, timedelta

def parse_date(date_str):
    if not date_str or date_str.strip() == "":
        return None
    try:
        return datetime.strptime(date_str.strip(), "%m/%d/%Y")
    except ValueError:
        return None

def is_business_day(date, holidays):
    if date.weekday() >= 5:
        return False
    if date in holidays:
        return False
    return True

def get_business_days_diff(start_date, end_date, holidays):
    # This is used to check if notice was removed no earlier than 10 business days after posted
    # We need to count business days between start and end
    count = 0
    current = start_date
    while current < end_date:
        current += timedelta(days=1)
        if is_business_day(current, holidays):
            count += 1
    return count

