import sys
import os
import json
import re
from datetime import datetime, timedelta

def parse_sql(file_path):
    """Parses the provided SQL files into a dictionary of tables and records."""
    content = ""
    with open(file_path, 'r') as f:
        content = f.read()

    tables = {}
    # Find CREATE TABLE statements to get table names
    create_matches = re.findall(r'CREATE TABLE (\w+) \(', content)
    for table_name in create_matches:
        tables[table_name] = []

    # Find INSERT INTO statements
    # This regex looks for INSERT INTO table_name (...) VALUES (...);
    # It handles multiple VALUES tuples per INSERT statement if they exist, 
    # though the provided format has one per statement.
    insert_pattern = re.compile(r"INSERT INTO (\w+) \([^)]*\) VALUES\s*(.*?);", re.DOTALL)
    for match in insert_pattern.finditer(content):
        table_name = match.group(1)
        values_block = match.group(2)

        # Split by tuples: (val1, val2, ...)
        # We look for patterns like (1, 'E-40912', 20538)
        tuple_pattern = re.compile(r"\((.*?)\)")
        tuples = tuple_pattern.findall(values_block)

        for t in tuples:
            # Split by comma, but be careful of commas inside quotes
            # Since the data is simple, we can use a regex to split by comma not inside quotes
            parts = []
            current = []
            in_quotes = False
            for char in t:
                if char == "'" :
                    in_quotes = not in_quotes
                    current.append(char)
                elif char == ',' and not in_quotes:
                    parts.append("".join(current).strip())
                    current = []
                else:
                    current.append(char)
            parts.append("".join(current).strip())

            # Clean up parts
            row = {}
            for i, val in enumerate(parts):
                if val.upper() == 'NULL':
                    row[i] = None
                elif val.startswith("'") and val.endswith("'"):
                    row[i] = val[1:-1]
                else:
                    try:
                        row[i] = int(val)
                    except ValueError:
                        row[i] = val
            if table_name in tables:
                tables[table_name].append(row)

    return tables

def epd_to_date(epd):
    if epd is None:
