import sys
import os
import json
import re
from datetime import datetime, timedelta

def parse_date(date_str):
    if not date_str:
        return None
    # Clean up common date formats found in the text
    date_str = date_str.strip()
    # Remove ordinal suffixes (st, nd, rd, th) from days
    date_str = re.sub(r'(\d+)(st|nd|rd|th)', r'\1', date_str)

    formats = [
        "%b %d, %Y",    # March 22nd, 2026 -> March 22, 2026
        "%d %b %Y",     # 17th Mar 2026 -> 17 Mar 2026
        "%B %d, %Y",    # March 22, 2026
        "%d %B %Y",     # 17 March 2026
        "%d %b %Y",     # 17 Mar 2026
        "%m/%d/%Y",     # 03/22/2026
        "%Y-%m-%d"      # 2026-03-22
    ]

    # Handle "July 20th, 2026" style
    # The regex above handles the 'th'

    for fmt in formats:
        try:
            return datetime.strptime(date_str, fmt)
        except ValueError:
            continue
    return None

def get_business_days_diff(start_date, end_date):
    # Simple business day calculation (excluding weekends)
    # Note: The prompt mentions US federal holidays, but since no holiday list is provided,
    # we implement standard weekend exclusion.
    count = 0
    curr = start_date
    while curr < end_date:
        curr += timedelta(days=1)
        if curr.weekday() < 5: # Monday to Friday
            count += 1
    return count

def solve():
